VM=$(az vm list -g resume-builder --query "[0].name" -o tsv) && rm -f ~/.ssh/rb_deploy ~/.ssh/rb_deploy.pub; ssh-keygen -t ed25519 -f ~/.ssh/rb_deploy -N "" -q -C github-deploy && az vm run-command invoke -g resume-builder -n $VM --command-id RunShellScript --scripts "echo '$(cat ~/.ssh/rb_deploy.pub)' > /home/azureuser/.ssh/authorized_keys && echo KEY_REPLACED" --query "value[0].message" -o tsv && echo "===== NEW PRIVATE KEY (save in Notepad, do NOT share) =====" && cat ~/.ssh/rb_deploy
